function superEllipsePoint(angle, width, height, exponent = .78) {
  const cos = Math.cos(angle);
  const sin = Math.sin(angle);
  const x = width * Math.sign(cos) * Math.pow(Math.abs(cos), exponent);
  const y = height * Math.sign(sin) * Math.pow(Math.abs(sin), exponent);
  return [x, y];
}

function makeLoft(sections, segments, material) {
  const positions = [];
  const uvs = [];
  const indices = [];
  segments = Math.max(8, segments);
  const seg = segments;

  sections.forEach((section, i) => {
    const exponent = section.e ?? .8;
    for (let j = 0; j < seg; j++) {
      const angle = j / seg * TAU;
      const [x, y] = superEllipsePoint(angle, section.w, section.h, exponent);
      positions.push(x, y + (section.y || 0), section.z);
      uvs.push(j / seg, i / (sections.length - 1));
    }
  });

  for (let i = 0; i < sections.length - 1; i++) {
    for (let j = 0; j < seg; j++) {
      const next = (j + 1) % seg;
      const a = i * seg + j;
      const b = (i + 1) * seg + j;
      const aNext = i * seg + next;
      const bNext = (i + 1) * seg + next;
      indices.push(a, b, aNext, b, bNext, aNext);
    }
  }

  // Caps keep silhouette clean and allow every side to be visible.
  const front = sections[0];
  const frontCenter = positions.length / 3;
  positions.push(0, front.y || 0, front.z);
  uvs.push(.5, .5);
  for (let j = 0; j < seg; j++) indices.push(frontCenter, j, (j + 1) % seg);

  const back = sections[sections.length - 1];
  const backStart = (sections.length - 1) * seg;
  const backCenter = positions.length / 3;
  positions.push(0, back.y || 0, back.z);
  uvs.push(.5, .5);
  for (let j = 0; j < seg; j++) {
    const next = (j + 1) % seg;
    indices.push(backCenter, backStart + next, backStart + j);
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  geometry.computeBoundingSphere();
  return new THREE.Mesh(geometry, material);
}

function plateGeometry(points, thickness = .1) {
  let pts = points.map(p => [p[0], p[1]]);
  let area = 0;
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i];
    const b = pts[(i + 1) % pts.length];
    area += a[0] * b[1] - b[0] * a[1];
  }
  if (area < 0) pts.reverse();
  const shape = new THREE.Shape();
  shape.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) shape.lineTo(pts[i][0], pts[i][1]);
  shape.closePath();
  const geometry = new THREE.ExtrudeGeometry(shape, {
    depth: thickness,
    steps: 1,
    bevelEnabled: true,
    bevelThickness: Math.min(.018, thickness * .28),
    bevelSize: Math.min(.018, thickness * .35),
    bevelSegments: 1,
    curveSegments: 3
  });
  geometry.rotateX(Math.PI / 2);
  geometry.translate(0, thickness / 2, 0);
  geometry.computeBoundingSphere();
  return geometry;
}

function addTube(parent, points, radius, material, closed = false) {
  const curve = new THREE.CatmullRomCurve3(points.map(p => new THREE.Vector3(...p)));
  const geometry = new THREE.TubeGeometry(curve, 28, radius, 5, closed);
  const mesh = new THREE.Mesh(geometry, material);
  parent.add(mesh);
  return mesh;
}

function meshOf(geometry, material, castShadow = true) {
  const mesh = new THREE.Mesh(geometry, material);
  mesh.castShadow = castShadow;
  mesh.receiveShadow = false;
  return mesh;
}

