function verticalPlateGeometry(points, thickness = .08) {
  let pts = points.map(p => [p[0], p[1]]);
  let area = 0;
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i];
    const b = pts[(i + 1) % pts.length];
    area += a[0] * b[1] - b[0] * a[1];
  }
  if (area < 0) pts.reverse();
  const shape = new THREE.Shape();
  shape.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) shape.lineTo(pts[i][0], pts[i][1]);
  shape.closePath();
  const geometry = new THREE.ExtrudeGeometry(shape, {
    depth: thickness,
    steps: 1,
    bevelEnabled: true,
    bevelThickness: Math.min(.012, thickness * .25),
    bevelSize: Math.min(.012, thickness * .25),
    bevelSegments: 1
  });
  geometry.rotateY(-Math.PI / 2);
  geometry.translate(thickness / 2, 0, 0);
  geometry.computeBoundingSphere();
  return geometry;
}

function createMissile(mats, length = 2.6, radius = .115) {
  const group = new THREE.Group();
  group.name = 'R-series missile';

  const bodyLength = length * .62;
  const body = meshOf(new THREE.CylinderGeometry(radius, radius * 1.03, bodyLength, 14, 1), mats.missileNose);
  body.rotation.x = Math.PI / 2;
  body.position.z = -length * .02;
  group.add(body);

  const nose = meshOf(new THREE.ConeGeometry(radius * 1.02, length * .25, 14), mats.radome);
  nose.rotation.x = Math.PI / 2;
  nose.position.z = bodyLength / 2 + length * .105;
  group.add(nose);

  const tail = meshOf(new THREE.CylinderGeometry(radius * .93, radius * .73, length * .13, 12), mats.metal);
  tail.rotation.x = Math.PI / 2;
  tail.position.z = -bodyLength / 2 - length * .055;
  group.add(tail);

  for (let i = 0; i < 4; i++) {
    const a = i / 4 * TAU + Math.PI / 4;
    const fin = meshOf(new THREE.BoxGeometry(radius * 2.5, .012, length * .17), mats.missileBand);
    fin.position.set(Math.cos(a) * radius * 1.55, Math.sin(a) * radius * 1.55, -length * .34);
    fin.rotation.z = a;
    group.add(fin);
  }

  const band = meshOf(new THREE.CylinderGeometry(radius * 1.045, radius * 1.045, .035, 14), mats.missileBand);
  band.rotation.x = Math.PI / 2;
  band.position.z = bodyLength * .32;
  group.add(band);

  const seeker = meshOf(new THREE.SphereGeometry(radius * .38, 10, 7), mats.darkMetal);
  seeker.position.z = bodyLength / 2 + length * .23;
  group.add(seeker);

  group.userData.length = length;
  group.userData.isMissile = true;
  return group;
}

function makeGearAssembly(mats, type = 'main') {
  const group = new THREE.Group();
  const isMain = type === 'main';
  const strutLength = isMain ? 1.03 : 1.06;
  const wheelRadius = isMain ? .34 : .28;

  const upper = meshOf(new THREE.CylinderGeometry(.038, .05, strutLength, 10), mats.metal);
  upper.position.y = -strutLength / 2;
  group.add(upper);

  const shiny = meshOf(new THREE.CylinderGeometry(.018, .026, strutLength * .62, 8), mats.hullLight);
  shiny.position.y = -strutLength * .46;
  group.add(shiny);

  const hub = meshOf(new THREE.CylinderGeometry(wheelRadius * .47, wheelRadius * .47, .14, 12), mats.hullDark);
  hub.rotation.z = Math.PI / 2;
  hub.position.y = -strutLength - wheelRadius * .38;
  group.add(hub);

  const tyre = meshOf(new THREE.TorusGeometry(wheelRadius, wheelRadius * .34, 8, 20), mats.rubber);
  tyre.rotation.y = Math.PI / 2;
  tyre.position.y = hub.position.y;
  group.add(tyre);

  const axle = meshOf(new THREE.CylinderGeometry(.025, .025, .24, 8), mats.metal);
  axle.rotation.z = Math.PI / 2;
  axle.position.y = hub.position.y;
  group.add(axle);

  const brace = meshOf(new THREE.CylinderGeometry(.018, .018, .5, 7), mats.metal);
  brace.rotation.z = isMain ? .52 : -.52;
  brace.position.set(isMain ? -.2 : .2, -strutLength * .64, 0);
  group.add(brace);

  const door = meshOf(new THREE.BoxGeometry(isMain ? .28 : .2, .42, .035), mats.hullDark);
  door.position.set(isMain ? -.16 : .11, -strutsSafeY(strutLength), .1);
  group.add(door);

  group.traverse(o => { if (o.isMesh) { o.castShadow = true; } });
  return group;
}

function strutsSafeY(length) { return length * .38; }

